CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA public;


--
-- Name: link_expense_splits_to_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.link_expense_splits_to_user() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Link by email (if provided)
  IF NEW.email IS NOT NULL THEN
    UPDATE event_expense_splits
    SET user_id = NEW.id,
        pending_email = NULL,
        pending_phone = NULL,
        pending_name = NULL
    WHERE user_id IS NULL 
      AND pending_email = NEW.email;
  END IF;
  
  -- Link by phone (if email didn't match and phone is provided)
  IF NEW.phone IS NOT NULL THEN
    UPDATE event_expense_splits
    SET user_id = NEW.id,
        pending_email = NULL,
        pending_phone = NULL,
        pending_name = NULL
    WHERE user_id IS NULL 
      AND pending_phone = NEW.phone;
  END IF;
  
  RETURN NEW;
END;
$$;


